    pontos:[ { ico:"🔨", t:"Crime comum", d:"foro originário no Superior Tribunal de Justiça" }, { ico:"📜", t:"Responsabilidade", d:"mesmo foro, sem divisão por tipo de crime" }, { ico:"⚖️", t:"Originariamente", d:"o processo começa já no Superior Tribunal de Justiça" } ],
